const userQuery = 'How long should I boil eggs for? And is it since putting them in the stove or time starts counting only after the water begins to boil?';

const searchQueryPrompt = [
  'You convert user questions into concise web search queries.',
  '',
  'Return valid JSON only.',
  '',
  'Rules:',
  '- Do not answer the user question.',
  '- Create one search query that will retrieve trustworthy practical guidance.',
  '- Prefer simple wording.',
  '- Include key ambiguity from the user when relevant.',
  '- Set count to 5 unless more results are clearly needed.',
  '',
  'User question:',
  userQuery,
  '',
  'Return this exact JSON shape:',
  JSON.stringify({
    searchQuery: 'string',
    count: 5,
    country: 'US',
    search_lang: 'en',
    ui_lang: 'en-US',
    freshness: '',
    safesearch: 'moderate'
  }, null, 2)
].join('\n');

return {
  json: {
    userQuery,
    searchQueryPrompt
  }
};

const userQuery = $json.userQuery;
const searchQueryPrompt = $json.searchQueryPrompt;

return {
  json: {
    userQuery,
    searchQueryPrompt,
    openRouterBody: {
      model: 'deepseek/deepseek-v4-flash',
      messages: [
        {
          role: 'system',
          content: 'You are a search query planner. Return only valid JSON.'
        },
        {
          role: 'user',
          content: searchQueryPrompt
        }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.1,
      max_tokens: 300,
      stream: false
    }
  }
};

const response = $input.item.json || {};
const raw = response.choices?.[0]?.message?.content ?? response.output_text ?? response.text ?? '';

let parsed = {};
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  const match = String(raw).match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (_) {
      parsed = {};
    }
  }
}

const fallbackQuery = 'boil eggs how long start timer after water boils or when placed on stove';
const normalizeCount = (value) => {
  const parsedCount = Number.parseInt(value, 10);
  if (!Number.isFinite(parsedCount)) return 5;
  return Math.min(10, Math.max(1, parsedCount));
};

return {
  json: {
    userQuery: $('Hardcoded User Query').first().json.userQuery,
    searchQueryRawModelOutput: raw,
    searchQuery: String(parsed.searchQuery || fallbackQuery).trim(),
    count: normalizeCount(parsed.count),
    maxContentChars: 8000,
    requestTimeoutMs: 60000,
    country: parsed.country || 'US',
    search_lang: parsed.search_lang || 'en',
    ui_lang: parsed.ui_lang || 'en-US',
    freshness: parsed.freshness || '',
    safesearch: parsed.safesearch || 'moderate'
  }
};

const prompt = $json.finalAnswerPrompt;

return {
  json: {
    ...$json,
    openRouterBody: {
      model: 'deepseek/deepseek-v4-pro',
      messages: [
        {
          role: 'system',
          content: 'You answer using provided sources. Return only valid JSON.'
        },
        {
          role: 'user',
          content: prompt
        }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.2,
      max_tokens: 900,
      stream: false
    }
  }
};

const response = $input.item.json || {};
const raw = response.choices?.[0]?.message?.content ?? response.output_text ?? response.text ?? '';

let parsed = {};
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  const match = String(raw).match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (_) {
      parsed = {};
    }
  }
}

const prepared = $('Prepare Search Context').first().json;
const answer = String(parsed.answer || raw || '').trim();

return {
  json: {
    status: answer ? 'ok' : 'error',
    channel: 'poc_no_telegram_yet',
    userQuery: prepared.userQuery,
    searchQuery: prepared.searchQuery,
    searchStatus: prepared.searchStatus,
    recordCount: prepared.recordCount,
    answer,
    confidence: parsed.confidence || (answer ? 'medium' : 'low'),
    sourceNumbersUsed: Array.isArray(parsed.sourceNumbersUsed) ? parsed.sourceNumbersUsed : [],
    sources: prepared.sources,
    debug: {
      queryFormatterModel: 'deepseek/deepseek-v4-flash',
      answerModel: 'deepseek/deepseek-v4-pro',
      answerRawModelOutput: raw
    }
  }
};
